void fill_area(int x0, int x1, int y0, int y1, short int fill_color) {
  for (int y = y0; y <= y1; y++) {
    for (int x = x0; x <= x1; x++) {
      plot_pixel(x, y, fill_color);
    }
    update_hardware();
  }
}

void fill_shape(int minX, int minY, int maxX, int maxY, short int fill_color,
                short int edge_color) {
  for (int y = minY; y <= maxY; y++) {
    int xLeft = maxX, xRight = minX;
    for (int x = minX; x <= maxX; x++) {
      if (get_pixel(x, y) == edge_color) {
        if (x < xLeft) xLeft = x;
        if (x > xRight) xRight = x;
      }
    }
    for (int x = xLeft; x <= xRight; x++) {
      plot_pixel(x, y, fill_color);
    }
    update_hardware();
  }
}

void draw_line(int x0, int y0, int x1, int y1, short int line_color) {
  bool is_steep = abs(y1 - y0) > abs(x1 - x0);
  if (is_steep) {
    swap(&x0, &y0);
    swap(&x1, &y1);
  }
  if (x0 > x1) {
    swap(&x0, &x1);
    swap(&y0, &y1);
  }
  int y_step = 0;
  int deltax = x1 - x0;
  int deltay = abs(y1 - y0);
  int error = -(deltax / 2);
  int y = y0;
  if (y0 < y1) {
    y_step = 1;
  } else {
    y_step = -1;
  }
  for (int x = x0; x < x1; x++) {
    if (is_steep)
      plot_pixel(y, x, line_color);
    else
      plot_pixel(x, y, line_color);
    error = error + deltay;
    if (error > 0) {
      y = y + y_step;
      error = error - deltax;
    }
  }
}

void draw_circle(int cx, int cy, int radius, short int color) {
  int x = 0;
  int y = radius;
  int d = 1 - radius;
  while (x <= y) {
    plot_pixel(cx + x, cy + y, color);
    plot_pixel(cx - x, cy + y, color);
    plot_pixel(cx + x, cy - y, color);
    plot_pixel(cx - x, cy - y, color);
    plot_pixel(cx + y, cy + x, color);
    plot_pixel(cx - y, cy + x, color);
    plot_pixel(cx + y, cy - x, color);
    plot_pixel(cx - y, cy - x, color);
    if (d < 0) {
      d = d + 2 * x + 3;
    } else {
      d = d + 2 * (x - y) + 5;
      y--;
    }
    x++;
  }
}

void draw_digit(int digit, int x, int y, short int color) {
  for (int row = 0; row < 5; row++) {
    int mask = digits[digit][row];
    if (mask & 0b100) plot_pixel(x, y + row, color);
    if (mask & 0b010) plot_pixel(x + 1, y + row, color);
    if (mask & 0b001) plot_pixel(x + 2, y + row, color);
  }
}

void draw_char(char ch, int x, int y, int scale, short colour) {
  if (ch < 'A' || ch > 'Z') return;
  int row, col, dx, dy;
  for (row = 0; row < 7; row++) {
    int byte = characters[ch - 'A'][row];
    for (col = 0; col < 5; col++) {
      if (byte & (0x10 >> col)) {
        for (dy = 0; dy < scale; dy++)
          for (dx = 0; dx < scale; dx++)
            plot_pixel(x + col * scale + dx, y + row * scale + dy, colour);
      }
    }
  }
}

